rollback.sql:
ALTER TABLE admin_audit_entries
    DROP CONSTRAINT IF EXISTS ck_admin_audit_entries_related_subject_pair,
    DROP CONSTRAINT IF EXISTS ck_admin_audit_entries_subject_pair;

changeSet.sql:
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = u.id FROM users u WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'users' AND u.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'COMPANY', subject_id = c.id FROM companies c WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'companies' AND c.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = v.user_id FROM user_verifications v WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'identity-verifications' AND v.id::text = e.resource_id AND v.user_id IS NOT NULL;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = COALESCE(r.subject_id, r.user_id) FROM account_deletion_requests r WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'account-deletions' AND r.id::text = e.resource_id AND COALESCE(r.subject_id, r.user_id) IS NOT NULL;
UPDATE admin_audit_entries e SET subject_type = 'COMPANY', subject_id = ci.company_id FROM company_images ci WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'images' AND ci.image_id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' ELSE 'USER' END, subject_id = COALESCE(j.company_id, j.creator_id) FROM job_images ji JOIN jobs j ON j.id = ji.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'images' AND ji.image_id::text = e.resource_id AND COALESCE(j.company_id, j.creator_id) IS NOT NULL;
UPDATE admin_audit_entries e SET subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' ELSE 'USER' END, subject_id = COALESCE(j.company_id, j.creator_id) FROM jobs j WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'jobs' AND j.id::text = e.resource_id AND COALESCE(j.company_id, j.creator_id) IS NOT NULL;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = b.user_id FROM bank_accounts b WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'bank-account-verifications' AND b.verification_reference = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = a.worker_id, related_subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' WHEN j.creator_id IS NOT NULL THEN 'USER' END, related_subject_id = COALESCE(j.company_id, j.creator_id) FROM job_assignments a JOIN jobs j ON j.id = a.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'job-assignments' AND a.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = p.worker_id FROM payouts p WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'payouts' AND p.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = a.worker_id, related_subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' WHEN j.creator_id IS NOT NULL THEN 'USER' END, related_subject_id = COALESCE(j.company_id, j.creator_id) FROM payments p JOIN job_assignments a ON a.id = p.job_assignment_id JOIN jobs j ON j.id = a.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'payments' AND p.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = 'USER', subject_id = a.worker_id, related_subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' WHEN j.creator_id IS NOT NULL THEN 'USER' END, related_subject_id = COALESCE(j.company_id, j.creator_id) FROM disputes d JOIN job_assignments a ON a.id = d.job_assignment_id JOIN jobs j ON j.id = a.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'disputes' AND d.id::text = e.resource_id;
UPDATE admin_audit_entries e SET subject_type = CASE WHEN r.reported_user_id IS NOT NULL THEN 'USER' WHEN j.company_id IS NOT NULL THEN 'COMPANY' ELSE 'USER' END, subject_id = COALESCE(r.reported_user_id, j.company_id, j.creator_id) FROM reports r LEFT JOIN jobs j ON j.id = r.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'reports' AND r.id::text = e.resource_id AND COALESCE(r.reported_user_id, j.company_id, j.creator_id) IS NOT NULL;
UPDATE admin_audit_entries e SET subject_type = 'COMPANY', subject_id = ci.company_id FROM reports r JOIN company_images ci ON ci.image_id = r.image_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'reports' AND r.id::text = e.resource_id AND r.reported_user_id IS NULL AND r.job_id IS NULL;
UPDATE admin_audit_entries e SET subject_type = CASE WHEN j.company_id IS NOT NULL THEN 'COMPANY' ELSE 'USER' END, subject_id = COALESCE(j.company_id, j.creator_id) FROM reports r JOIN job_images ji ON ji.image_id = r.image_id JOIN jobs j ON j.id = ji.job_id WHERE (e.mutating OR e.sensitivity <> 'NORMAL') AND e.subject_id IS NULL AND e.resource_type = 'reports' AND r.id::text = e.resource_id AND r.reported_user_id IS NULL AND r.job_id IS NULL AND COALESCE(j.company_id, j.creator_id) IS NOT NULL;
